codeExample.bad:
/* A promotional banner strobes between two bright colors 5 times
   per second, covering a large area of the viewport */
.flash-banner {
  animation: strobe 0.2s infinite;
}
@keyframes strobe {
  0%, 100% { background-color: #ffffff; }
  50% { background-color: #ff0000; }
}

codeExample.good:
/* The same promotional message uses a slow, low-contrast fade
   instead of a rapid high-contrast strobe */
.flash-banner {
  animation: fade 3s infinite;
}
@keyframes fade {
  0%, 100% { background-color: #f5f5f5; }
  50% { background-color: #e0e0e0; }
}
